BEGIN;
SELECT id FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000124' FOR UPDATE;
CREATE TEMP TABLE upper_target ON COMMIT DROP AS SELECT id FROM "Exercise" WHERE id='00000000-0000-4000-8000-000000000124' AND "ownerUserId" IS NULL AND name='Desenvolvimento com Halteres' AND "anatomyReview" IS NULL AND (SELECT string_agg(m.role::text||':'||m."muscleGroup"::text,'|' ORDER BY m.role::text||':'||m."muscleGroup"::text) FROM "ExerciseMuscle" m WHERE m."exerciseId"="Exercise".id)='PRIMARY:SHOULDERS|SECONDARY:BACK|SECONDARY:TRICEPS';
INSERT INTO "ExerciseMuscle"(id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,id,'CHEST'::"MuscleGroup",'SECONDARY'::"MuscleRole",NOW() FROM upper_target;
INSERT INTO "ExerciseMuscle"(id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,id,'FOREARMS'::"MuscleGroup",'SECONDARY'::"MuscleRole",NOW() FROM upper_target;
INSERT INTO "ExerciseMuscle"(id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,id,'CORE'::"MuscleGroup",'SECONDARY'::"MuscleRole",NOW() FROM upper_target;
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-11-18.upper.1","reviewedAt":"2026-11-18T10:31:38.542Z","variant":"Desenvolvimento bilateral sentado com halteres, encosto vertical e pegada pronada; não é Arnold press.","aliases":["Desenvolvimento com Halteres"],"participants":[{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"PRIMARY","aliases":["ombro anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"DELTOID_MEDIAL","label":"Deltoide lateral","muscleGroup":"SHOULDERS","role":"PRIMARY","aliases":["deltoide médio","deltoide acromial"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"TRICEPS_BRACHII","label":"Tríceps braquial","muscleGroup":"TRICEPS","role":"SECONDARY","aliases":["tríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"SECONDARY","aliases":["peitoral","peito"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"SECONDARY","aliases":["trapézio superior","trapézio inferior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"SERRATUS_ANTERIOR","label":"Serrátil anterior","muscleGroup":"BACK","role":"SECONDARY","aliases":["serrátil","controle escapular"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"SUPRASPINATUS","label":"Supraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["supraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"TERES_MINOR","label":"Redondo menor","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"SUBSCAPULARIS","label":"Subescapular","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ANATOMY","PRESS_2013"]}],"sources":[{"id":"PRESS_2013","title":"Saeterbakken e Fimland (2013): Effects of body position and loading modality on muscle activity and strength in shoulder presses","url":"https://pubmed.ncbi.nlm.nih.gov/23096062/","limitation":"EMG aguda de variantes sentadas/em pé e barra/halteres; não mede este avatar nem determina hipertrofia ou ângulos universais."},{"id":"PRESS_2022","title":"Coratella et al. (2022): Front vs Back and Barbell vs Machine Overhead Press","url":"https://doi.org/10.3389/fphys.2022.825880","limitation":"Oito fisiculturistas; comparação sentada com barra/máquina. Informa participantes, sem extrapolar magnitudes para militar em pé ou halteres."},{"id":"SCAPULA_2005","title":"Ebaugh, McClure e Karduna (2005): Three-dimensional scapulothoracic motion during active and passive arm elevation","url":"https://doi.org/10.1016/j.clinbiomech.2005.03.008","limitation":"Cinemática/EMG experimental da elevação, não desenvolvimento carregado deste avatar. Rotação superior e inclinação posterior são qualitativas; o ritmo não é uma proporção fixa universal."},{"id":"ANATOMY","title":"OpenStax Anatomy and Physiology 2e: Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Referência anatômica de ações e estabilização; não mede EMG das execuções modeladas."}],"notes":"Revisão individual 3D: Desenvolvimento bilateral sentado com halteres, encosto vertical e pegada pronada; não é Arnold press. Participação muscular ilustrativa, sem percentuais de EMG, isolamento ou promessa de resultado.  Ângulos, cadência e apoios são decisões ilustrativas deste avatar. Supraespinal e subescapular não têm superfícies separadas neste atlas e não são pintados por substituição. Sem inferir ênfase entre cabeças do bíceps. Escápulas acompanham a elevação; cotovelos e punhos preservam seus próprios eixos.","instructions":{"description":"Desenvolvimento bilateral sentado com halteres, encosto vertical e pegada pronada; não é Arnold press.","setup":"Sente-se com quadril apoiado, costas sustentadas pelo encosto e pés no chão. Posicione os halteres ao lado da cabeça, cotovelos um pouco à frente do tronco e punhos alinhados.","execution":"Estenda os cotovelos e eleve os braços com trajetória própria de cada halter, aproximando-os moderadamente no alto sem bater um no outro. Permita que as escápulas acompanhem a elevação. Desça de forma controlada, sem perder os apoios nem exagerar a extensão lombar.","tips":"Não gire os halteres como no Arnold press. O banco é vertical nesta demonstração; ajuste carga e amplitude à sua mobilidade. Cores mostram participação ilustrativa, sem medir esforço ou EMG."}}'::jsonb,"updatedAt"=NOW() WHERE id IN(SELECT id FROM upper_target);
DROP TABLE upper_target;
COMMIT;
